 //==================================================================================================
 // Imports
 //==================================================================================================

 use vstd::prelude::*;
 #[cfg(verus_keep_ghost)]
 include!("phys.spec.rs");
 #[cfg(verus_keep_ghost)]
 include!("phys.proof.rs");

 use crate::hal::mem::types::address::{
     Address,
     FrameAddress,
     VirtualAddress,
 };
 use ::arch::mem::{
     self,
     paging::FrameNumber,
 };
 use ::sys::{
     error::{
         Error,
         ErrorCode,
     },
     mm::Alignment,
 };
 #[cfg(verus_keep_ghost)]
 use ::vstd::prelude::*;

 //==================================================================================================
 // Structures
